with j as (select * from jsonb_to_recordset($law7d0002$[{"code_id":"APK_RF","article_number":"138.5","version_date":"2002-07-24","article_text":"1. Стороны вправе урегулировать спор путем использования примирительной процедуры с участием судебного примирителя (судебное примирение).\n\n2. Судебное примирение осуществляется на основе принципов независимости, беспристрастности и добросовестности судебного примирителя.\n\nПорядок проведения судебного примирения и требования к судебному примирителю определяются настоящим Кодексом и Регламентом проведения судебного примирения, утверждаемым Верховным Судом Российской Федерации.\n\n3. Судебным примирителем является судья в отставке. Список судебных примирителей формируется и утверждается Пленумом Верховного Суда Российской Федерации на основе предложений арбитражных судов о кандидатурах судебных примирителей из числа судей в отставке, изъявивших желание выступать в качестве судебного примирителя.\n\nСудебный примиритель участвует в процедуре судебного примирения с учетом положений настоящего Кодекса и законодательства о статусе судей в Российской Федерации.\n\n4. Кандидатура судебного примирителя определяется по взаимному согласию сторон из списка судебных примирителей и утверждается определением суда.\n\n5. В целях соотнесения и сближения позиций сторон по делу и выявления дополнительных возможностей для урегулирования спора с учетом интересов сторон, оказания им содействия в достижении взаимоприемлемого результата примирения, основанного также на понимании и оценке сторонами обоснованности заявленных требований и возражений, судебный примиритель вправе вести переговоры со сторонами, другими лицами, участвующими в деле, изучать представленные сторонами документы, знакомиться с материалами дела с согласия арбитражного суда и осуществлять другие действия, необходимые для эффективного урегулирования спора и предусмотренные Регламентом проведения судебного примирения, в том числе давать сторонам рекомендации в целях скорейшего урегулирования спора и сохранения между сторонами деловых отношений.\n\nСудебный примиритель не является участником судебного разбирательства и не вправе совершать действия, влекущие за собой возникновение, изменение либо прекращение прав или обязанностей лиц, участвующих в деле, и других участников арбитражного процесса.\n\nСудья вправе запросить информацию о ходе примирительной процедуры не чаще чем один раз в четырнадцать календарных дней.\n\n6. Порядок и условия оплаты труда судей, пребывающих в отставке и осуществляющих функции судебных примирителей, определяются Правительством Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.5. Судебное примирение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1469b3e0e6089e4781155e7d7b385f36b28ab0525c8683976547c20026c90099"},{"code_id":"APK_RF","article_number":"138.6","version_date":"2002-07-24","article_text":"1. Результатами примирения лиц, участвующих в деле, могут быть, в частности:\n\n1) мировое соглашение в отношении всех или части заявленных требований;\n\n2) частичный или полный отказ от иска;\n\n3) частичное или полное признание иска;\n\n4) полный или частичный отказ от апелляционной, кассационной жалобы, надзорной жалобы (представления);\n\n5) признание обстоятельств, на которых другая сторона основывает свои требования или возражения;\n\n6) соглашение по обстоятельствам дела;\n\n7) подписание письма-согласия на государственную регистрацию товарного знака.\n\n2. Признание обстоятельств, признание иска (требований), отказ от иска (требований) полностью или в части принимаются арбитражным судом в порядке, установленном настоящим Кодексом.\n\n3. Признание обстоятельств, на которых другая сторона основывает свои требования или возражения, может быть осуществлено в форме одностороннего заявления о согласии с позицией другой стороны или в форме соглашения по обстоятельствам дела.\n\n(Дополнение статьей - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 138.6. Результаты примирительных процедур","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e83456382b23fb39526728e806741446245ba489096c5fec5a241ca39761c6d0"},{"code_id":"APK_RF","article_number":"14","version_date":"2002-07-24","article_text":"1. При применении норм иностранного права арбитражный суд устанавливает содержание этих норм в соответствии с их официальным толкованием, практикой применения и доктриной в соответствующем иностранном государстве.\n\n2. В целях установления содержания норм иностранного права суд может обратиться в установленном порядке за содействием и разъяснением в Министерство юстиции Российской Федерации и иные компетентные органы или организации Российской Федерации и за границей либо привлечь экспертов.\n\nЛица, участвующие в деле, могут представлять документы, подтверждающие содержание норм иностранного права, на которые они ссылаются в обоснование своих требований или возражений, и иным образом содействовать суду в установлении содержания этих норм.\n\nПо требованиям, связанным с осуществлением сторонами предпринимательской и иной экономической деятельности, обязанность доказывания содержания норм иностранного права может быть возложена судом на стороны.\n\n3. Если содержание норм иностранного права, несмотря на принятые в соответствии с настоящей статьей меры, в разумные сроки не установлено, арбитражный суд применяет соответствующие нормы российского права.","article_title":"Статья 14. Применение норм иностранного права","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2ab390e3c296616410f88591dd711f00f3ea6fc5051f9f1c2dab68b12fed3641"},{"code_id":"APK_RF","article_number":"140","version_date":"2002-07-24","article_text":"1. Мировое соглашение заключается в письменной форме и подписывается сторонами или их представителями при наличии у них полномочий на заключение мирового соглашения, специально предусмотренных в доверенности или ином документе, подтверждающих полномочия представителя.\n\n2. Мировое соглашение должно содержать согласованные сторонами сведения об условиях, о размере и о сроках исполнения обязательств друг перед другом или одной стороной перед другой.\n\nВ мировом соглашении могут содержаться условия об отсрочке или о рассрочке исполнения обязательств ответчиком, об уступке прав требования, о полном или частичном прощении либо признании долга, о распределении судебных расходов, санкции за его неисполнение или ненадлежащее исполнение и иные условия, не противоречащие федеральному закону. (В редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n3. Если в мировом соглашении отсутствует условие о распределении судебных расходов, арбитражный суд разрешает этот вопрос при утверждении мирового соглашения в общем порядке, установленном настоящим Кодексом.\n\n4. Мировое соглашение составляется и подписывается в количестве экземпляров, превышающем на один экземпляр количество лиц, заключивших мировое соглашение; один из этих экземпляров приобщается арбитражным судом, утвердившим мировое соглашение, к материалам дела.","article_title":"Статья 140. Форма и содержание мирового соглашения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e26a6a3a48f114f89ceaf15275b410814d9656bf930ebb6218dc05e51d35aef9"},{"code_id":"APK_RF","article_number":"141","version_date":"2002-07-24","article_text":"1. Мировое соглашение утверждается арбитражным судом, в производстве которого находится дело. В случае, если мировое соглашение заключено в процессе исполнения судебного акта, оно представляется на утверждение арбитражного суда первой инстанции по месту исполнения судебного акта или в арбитражный суд, принявший указанный судебный акт.\n\n2. Вопрос об утверждении мирового соглашения рассматривается арбитражным судом в судебном заседании. Лица, участвующие в деле, извещаются о времени и месте судебного заседания.\n\n3. В случае неявки в судебное заседание лиц, заключивших мировое соглашение и извещенных надлежащим образом о времени и месте судебного заседания, вопрос об утверждении мирового соглашения не рассматривается арбитражным судом, если от этих лиц не поступило заявление о рассмотрении данного вопроса в их отсутствие.\n\nПри рассмотрении вопроса об утверждении мирового соглашения в случае обжалования судебного акта или его исполнения законность и обоснованность соответствующего судебного акта не проверяются.\n\n(Часть в редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\nПри рассмотрении вопроса об утверждении мирового соглашения арбитражный суд вправе предложить сторонам исключить из мирового соглашения отдельные условия, противоречащие закону или нарушающие права и законные интересы других лиц.\n\n(Часть в редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n1) утверждение мирового соглашения или отказ в утверждении мирового соглашения;\n\n2) условия мирового соглашения;\n\n3) возвращение истцу из федерального бюджета части уплаченной им государственной пошлины в размерах, установленных федеральными законами о налогах и сборах;\n\n4) распределение судебных расходов.\n\n(Часть в редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\nУтверждение мирового соглашения в судах апелляционной, кассационной и надзорной инстанций по предмету заявленных требований влечет за собой отмену судебного акта и прекращение производства по делу.\n\nУтверждение мирового соглашения, заключенного в процессе исполнения судебного акта, влечет за собой прекращение исполнения этого судебного акта при оставлении его в силе. На это указывается в определении суда.\n\nУтверждение мирового соглашения, заключенного при рассмотрении заявления о распределении судебных расходов, понесенных в судах первой, апелляционной, кассационной и надзорной инстанций, влечет за собой прекращение производства по заявлению о распределении судебных расходов.\n\n(Дополнение частью - Федеральный закон от 26.07.2019 № 197-ФЗ)","article_title":"Статья 141. Утверждение арбитражным судом мирового соглашения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"43390ec411e8b7309dc544af9b20dfa748fc52e90f5ac821af11ab8a4482a639"},{"code_id":"APK_RF","article_number":"142","version_date":"2002-07-24","article_text":"1. Мировое соглашение исполняется лицами, его заключившими, добровольно в порядке и в сроки, которые предусмотрены этим соглашением.\n\n2. Мировое соглашение, не исполненное добровольно, подлежит принудительному исполнению по правилам раздела VII настоящего Кодекса на основании исполнительного листа, выдаваемого арбитражным судом по ходатайству лица, заключившего мировое соглашение.","article_title":"Статья 142. Исполнение мирового соглашения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"43c1c144f8981ef5de080f41069bb91f5cfb2e701d16c27515fafea82c5c78fa"},{"code_id":"APK_RF","article_number":"143","version_date":"2002-07-24","article_text":"1. Арбитражный суд обязан приостановить производство по делу в случае:\n\n1) невозможности рассмотрения данного дела до разрешения другого дела, рассматриваемого Конституционным Судом Российской Федерации, Верховным Судом Российской Федерации, судом общей юрисдикции, арбитражным судом; (В редакции  федеральных законов от 14.07.2022 № 337-ФЗ, от 25.12.2023 № 667-ФЗ)\n\n2) участия гражданина, являющегося стороной в деле, в боевых действиях в составе Вооруженных Сил Российской Федерации, других войск, воинских формирований и органов, созданных в соответствии с законодательством Российской Федерации, в проведении контртеррористической операции, призыва его на военную службу по мобилизации, заключения им контракта о добровольном содействии в выполнении задач, возложенных на Вооруженные Силы Российской Федерации или войска национальной гвардии Российской Федерации, выполнения им задач в условиях чрезвычайного или военного положения, вооруженного конфликта, если такой гражданин не заявил ходатайство о рассмотрении дела в его отсутствие; (В редакции  федеральных законов от 29.12.2022 № 603-ФЗ, от 25.12.2023 № 639-ФЗ)\n\n3) смерти гражданина, являющегося стороной в деле или третьим лицом, заявляющим самостоятельные требования относительно предмета спора, если спорное правоотношение допускает правопреемство; (В редакции Федерального закона от 22.04.2013 № 61-ФЗ)\n\n4) утраты гражданином, являющимся стороной в деле, дееспособности.\n\n2. Арбитражный суд приостанавливает производство по делу и в иных предусмотренных федеральным законом случаях.","article_title":"Статья 143. Обязанность арбитражного суда приостановить производство по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8637bd3ac1201fc580e2bdb9426fc2fd7b5b409bebc9338177f7e834d94e9380"},{"code_id":"APK_RF","article_number":"144","version_date":"2002-07-24","article_text":"Арбитражный суд вправе приостановить производство по делу в случае:\n\n1) назначения арбитражным судом экспертизы;\n\n2) реорганизации организации, являющейся лицом, участвующим в деле;\n\n3) привлечения гражданина, являющегося лицом, участвующим в деле, для выполнения государственной об\n\nязанности;\n\n4) нахождения гражданина, являющегося лицом, участвующим в деле, в лечебном учреждении или длительной служебной командировке;\n\n5) рассмотрения международным судом, судом иностранного государства другого дела, решение по которому может иметь значение для рассмотрения данного дела;\n\n6) участия гражданина, осуществляющего полномочия единоличного исполнительного органа организации, являющейся лицом, участвующим в деле, в боевых действиях в составе Вооруженных Сил Российской Федерации, других войск, воинских формирований и органов, созданных в соответствии с законодательством Российской Федерации, в проведении контртеррористической операции, призыва его на военную службу по мобилизации, заключения им контракта о добровольном содействии в выполнении задач, возложенных на Вооруженные Силы Российской Федерации или войска национальной гвардии Российской Федерации, выполнения им задач в условиях чрезвычайного или военного положения, вооруженного конфликта, если рассмотрение дела без участия такого гражданина невозможно и полномочия по управлению указанной организацией не переданы им в порядке, установленном законодательством Российской Федерации. (Дополнение пунктом - Федеральный закон от 29.12.2022 № 603-ФЗ) (В редакции  Федерального закона от 25.12.2023 № 639-ФЗ)","article_title":"Статья 144. Право арбитражного суда приостановить производство по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"029eea7f040aef0c579dc2c366436a6cf4e9083bb9d04db7761101c6904ed846"},{"code_id":"APK_RF","article_number":"145","version_date":"2002-07-24","article_text":"Производство по делу приостанавливается:\n\n1) в случаях, предусмотренных пунктом 1 части 1 статьи 143 и пунктом 5 статьи 144 настоящего Кодекса, до вступления в законную силу судебного акта соответствующего суда;\n\n2) в случаях, предусмотренных пунктом 2 части 1 статьи 143 и пунктами 4 и 6 статьи 144 настоящего Кодекса, до устранения обстоятельств, послуживших основанием для приостановления производства по делу; (В редакции  Федерального закона от 29.12.2022 № 603-ФЗ)\n\n3) в случаях, предусмотренных пунктами 3 и 4 части 1 статьи 143 и пунктом 2 статьи 144 настоящего Кодекса, до определения правопреемника лица, участвующего в деле, или назначения недееспособному лицу представителя;\n\n4) в случае, предусмотренном пунктом 1 статьи 144 настоящего Кодекса, до истечения срока, установленного арбитражным судом.","article_title":"Статья 145. Сроки приостановления производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2637cee6264ddd3e37b7272bae9d8148b1c45db7e7e801fb9f2ed10413063712"},{"code_id":"APK_RF","article_number":"146","version_date":"2002-07-24","article_text":"Арбитражный суд возобновляет производство по делу по заявлению лиц, участвующих в деле, или по своей инициативе после устранения обстоятельств, вызвавших его приостановление, либо до их устранения по заявлению лица, по ходатайству которого производство по делу было приостановлено.","article_title":"Статья 146. Возобновление производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ac6eeffc526fb3d58fb4062bbf6cd20d9d45666b2db78e1efca3d573c9416802"},{"code_id":"APK_RF","article_number":"147","version_date":"2002-07-24","article_text":"1. О приостановлении производства по делу, его возобновлении или об отказе в возобновлении арбитражный суд выносит определение.\n\nКопии определения направляются лицам, участвующим в деле.\n\n2. Определение арбитражного суда о приостановлении производства по делу, об отказе в возобновлении производства по делу может быть обжаловано.","article_title":"Статья 147. Порядок приостановления и возобновления производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6ae203152800c60ecd2dc2181a19ae2a503b019a8ed6df9a2c7e41787c7105ba"},{"code_id":"APK_RF","article_number":"148","version_date":"2002-07-24","article_text":"1) в производстве арбитражного суда, суда общей юрисдикции, третейского суда имеется дело по спору между теми же лицами, о том же предмете и по тем же основаниям;\n\n2) истцом не соблюден претензионный или иной досудебный порядок урегулирования спора с ответчиком, за исключением случаев, если его соблюдение не предусмотрено федеральным законом; (В редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n3) при рассмотрении заявления об установлении фактов, имеющих юридическое значение, выясняется, что возник спор о праве;\n\n4) заявлено требование, которое в соответствии с федеральным законом должно быть рассмотрено в деле о банкротстве;\n\n5) имеется соглашение сторон о рассмотрении данного спора третейским судом, если любая из сторон не позднее дня представления своего первого заявления по существу спора в арбитражном суде первой инстанции заявит по этому основанию возражение в отношении рассмотрения дела в арбитражном суде, за исключением случаев, если арбитражный суд установит, что это соглашение недействительно, утратило силу или не может быть исполнено;\n\n6) стороны заключили соглашение о передаче спора на разрешение третейского суда во время судебного разбирательства до принятия судебного акта, которым заканчивается рассмотрение дела по существу, если любая из сторон заявит по этому основанию возражение в отношении рассмотрения дела в арбитражном суде, за исключением случаев, если арбитражный суд установит, что это соглашение недействительно, утратило силу или не может быть исполнено;\n\n7) исковое заявление не подписано или подписано лицом, не имеющим права подписывать его, либо лицом, должностное положение которого не указано;\n\n8) заявлено исковое требование о взыскании судебных расходов, которое подлежит рассмотрению в соответствии со статьей 112 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\n9) истец повторно не явился в судебное заседание, в том числе по вызову суда, и не заявил ходатайство о рассмотрении дела в его отсутствие или об отложении судебного разбирательства, а ответчик не требует рассмотрения дела по существу. (Дополнение пунктом - Федеральный закон от 27.07.2010 № 228-ФЗ)","article_title":"Статья 148. Основания для оставления искового заявления без рассмотрения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a0a4c50495985fb4afd8aa1413be80db9bdb1a5045a5e93fbf7f5555ca9be4de"},{"code_id":"APK_RF","article_number":"149","version_date":"2002-07-24","article_text":"1. В случае оставления искового заявления без рассмотрения производство по делу заканчивается вынесением определения.\n\nВ определении арбитражный суд указывает основания для оставления искового заявления без рассмотрения, а также решает вопрос о возврате государственной пошлины из федерального бюджета в случае, предусмотренном частью 2 статьи 148 настоящего Кодекса. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nКопии определения направляются лицам, участвующим в деле.\n\n2. Определение арбитражного суда об оставлении искового заявления без рассмотрения может быть обжаловано.\n\n3. Оставление искового заявления без рассмотрения не лишает истца права вновь обратиться в арбитражный суд с заявлением в общем порядке после устранения обстоятельств, послуживших основанием для оставления заявления без рассмотрения.","article_title":"Статья 149. Порядок и последствия оставления искового заявления без рассмотрения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"646b16b49394410f8fc2c9b69e860430370303abaae95c15010b231e82fab2ea"},{"code_id":"APK_RF","article_number":"15","version_date":"2002-07-24","article_text":"1. Арбитражный суд принимает судебные акты в форме судебного приказа, решения, постановления, определения.\n\n2. Судебный акт, вынесенный арбитражным судом первой инстанции в порядке приказного производства, именуется судебным приказом.\n\nСудебный акт, принятый арбитражным судом первой инстанции при рассмотрении дела по существу, именуется решением.\n\n3. Судебные акты, принимаемые арбитражными судами апелляционной инстанции и судами кассационной инстанции, образованными в соответствии с Федеральным конституционным законом от 28 апреля 1995 года № 1-ФКЗ \"Об арбитражных судах в Российской Федерации\", по результатам рассмотрения апелляционных и кассационных жалоб, именуются постановлениями. Судебные акты, выносимые Верховным Судом Российской Федерации по результатам рассмотрения кассационных жалобы, представления в порядке, установленном статьями 2911 - 29115 настоящего Кодекса, именуются определениями. Судебные акты, принимаемые Президиумом Верховного Суда Российской Федерации по результатам рассмотрения надзорных жалобы, представления в порядке, установленном статьями 3081 - 30813 настоящего Кодекса, именуются постановлениями.\n\nВсе иные судебные акты арбитражных судов, принимаемые в ходе осуществления судопроизводства, именуются определениями.\n\n4. Принимаемые арбитражным судом судебные приказы, решения, постановления, определения должны быть законными, обоснованными и мотивированными.\n\n5. Судебный акт, за исключением акта, содержащего сведения, составляющие государственную или иную охраняемую законом тайну, если дело рассмотрено в закрытом судебном заседании, может быть выполнен в форме электронного документа, который подписывается судьей усиленной квалифицированной электронной подписью. В случае, если судебный акт принят судом коллегиально, он подписывается всеми судьями, рассматривавшими дело, усиленной квалифицированной электронной подписью.\n\nПри выполнении судебного акта в форме электронного документа дополнительно выполняется экземпляр данного судебного акта на бумажном носителе.\n\n(Дополнение частью - Федеральный закон от 23.06.2016 № 220-ФЗ)\n\n(Статья в редакции Федерального закона от 02.03.2016 № 47-ФЗ)","article_title":"Статья 15. Судебные акты арбитражного суда, Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1ba77100a4b229b23d738d5fcb63ae1ac98b29ee5fd5229645a1622a5f3b783c"},{"code_id":"APK_RF","article_number":"150","version_date":"2002-07-24","article_text":"1. Арбитражный суд прекращает производство по делу, если установит, что:\n\n1) имеются основания, предусмотренные пунктом 1 части 1 статьи 1271 настоящего Кодекса; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) имеется вступивший в законную силу принятый по спору между теми же лицами, о том же предмете и по тем же основаниям судебный акт арбитражного суда, суда общей юрисдикции или компетентного суда иностранного государства, за исключением случаев, если арбитражный суд отказал в признании и приведении в исполнение решения иностранного суда;\n\n3) имеется принятое по спору между теми же лицами, о том же предмете и по тем же основаниям решение третейского суда, за исключением случаев, если арбитражный суд отказал в выдаче исполнительного листа на принудительное исполнение решения третейского суда либо если арбитражный суд отменил указанное решение; (В редакции Федерального закона от 29.12.2015 № 409-ФЗ)\n\n4) истец отказался от иска и отказ принят арбитражным судом;\n\n5) организация, являющаяся стороной в деле, ликвидирована;\n\n6) после смерти гражданина, являющегося стороной в деле, спорное правоотношение не допускает правопреемства;\n\n7) имеются основания, предусмотренные частью 7 статьи 194 настоящего Кодекса.","article_title":"Статья 150. Основания для прекращения производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0f63471fb90c31a726410e40ef5a078bd0fc54f76dbf4ef9de4ecf665b30ccf"},{"code_id":"APK_RF","article_number":"151","version_date":"2002-07-24","article_text":"1. О прекращении производства по делу арбитражный суд выносит определение.\n\nВ определении арбитражный суд указывает основания для прекращения производства по делу, а также разрешает вопросы о возврате государственной пошлины из федерального бюджета в случае, предусмотренном частью 1 статьи 150 настоящего Кодекса, и распределении между сторонами судебных расходов. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\nКопии определения направляются лицам, участвующим в деле.\n\n2. Определение арбитражного суда о прекращении производства по делу может быть обжаловано.","article_title":"Статья 151. Порядок и последствия прекращения производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"003bf58415329e24ddf14b81f4f958a7fce9ef29df6691c9d74f777f92f3c9e5"},{"code_id":"APK_RF","article_number":"152","version_date":"2002-07-24","article_text":"Дело по спору о сносе самовольной постройки или ее приведении в соответствие с предельными параметрами разрешенного строительства, реконструкции объектов капитального строительства, установленными правилами землепользования и застройки, документацией по планировке территории, или обязательными требованиями к параметрам объектов капитального строительства, установленными федеральными законами, об изъятии земельного участка из земель сельскохозяйственного назначения должно быть рассмотрено арбитражным судом первой инстанции в срок, не превышающий одного месяца со дня поступления заявления в арбитражный суд, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу. (Дополнение абзацем - Федеральный закон от 03.08.2018 № 340-ФЗ) (В редакции  Федерального закона от 05.12.2022 № 507-ФЗ)\n\n(Статья в редакции Федерального закона от 30.04.2010 № 69-ФЗ)","article_title":"Статья 152. Срок рассмотрения дела и принятия решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5fef23a0285c3ae6b846ecfd669658b717798c102cf30c0f2e02fda94b27a32e"},{"code_id":"APK_RF","article_number":"153","version_date":"2002-07-24","article_text":"1. Разбирательство дела осуществляется в судебном заседании арбитражного суда с обязательным извещением лиц, участвующих в деле, о времени и месте заседания.\n\n2. Судья, а при коллегиальном рассмотрении дела председательствующий в судебном заседании:\n\n1) открывает судебное заседание и объявляет, какое дело подлежит рассмотрению;\n\n2) проверяет явку в судебное заседание лиц, участвующих в деле, их представителей и иных участников арбитражного процесса, устанавливает их личность и проверяет полномочия; устанавливает, извещены ли надлежащим образом лица, не явившиеся в судебное заседание, и какие имеются сведения о причинах их неявки;\n\n3) выясняет вопрос о возможности слушания дела;\n\n4) объявляет состав арбитражного суда, сообщает, кто ведет протокол судебного заседания, кто участвует в качестве эксперта, переводчика, и разъясняет лицам, участвующим в деле, их право заявлять отводы;\n\n5) разъясняет лицам, участвующим в деле, и иным участникам арбитражного процесса их процессуальные права и обязанности;\n\n6) удаляет из зала судебного заседания явившихся свидетелей до начала их допроса;\n\n7) предупреждает переводчика об уголовной ответственности за заведомо неправильный перевод, эксперта за дачу заведомо ложного заключения, свидетелей (непосредственно перед их допросом) за дачу заведомо ложных показаний и отказ от дачи показаний;\n\n8) определяет с учетом мнений лиц, участвующих в деле, последовательность проведения процессуальных действий и продолжительность выступлений; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n9) выясняет, поддерживает ли истец иск, признает ли иск ответчик, не хотят ли стороны закончить дело мировым соглашением или применить процедуру медиации, о чем делаются соответствующие записи в протоколе судебного заседания; (В редакции Федерального закона от 27.07.2010 № 194-ФЗ)\n\n10) руководит судебным заседанием, обеспечивает условия для всестороннего и полного исследования доказательств и обстоятельств дела, обеспечивает рассмотрение заявлений и ходатайств лиц, участвующих в деле;\n\n11) принимает меры по обеспечению в судебном заседании надлежащего порядка.","article_title":"Статья 153. Судебное заседание арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"40a0e6597dd190a5c59bf854fb0ffe34ac4e6396de81c245f8392918d7cb0b2b"},{"code_id":"APK_RF","article_number":"153.1","version_date":"2002-07-24","article_text":"В случае, если лицу, участвующему в деле, иным участникам арбитражного процесса, находящимся в местах содержания под стражей или в местах отбывания лишения свободы, содействие в участии в судебном заседании путем использования систем видеоконференц-связи оказывает соответствующее учреждение, арбитражный суд, рассматривающий дело, выносит определение о проведении такого судебного заседания в соответствии со статьями 184 и 185 настоящего Кодекса. Копия определения арбитражного суда направляется в учреждение, которое обеспечивает проведение судебного заседания путем использования систем видеоконференц-связи в соответствии со статьей 1551 Гражданского процессуального кодекса Российской Федерации. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n(Дополнение частью - Федеральный закон от 01.05.2016 № 137-ФЗ)\n\n1) отсутствует техническая возможность для участия в судебном заседании с использованием систем видеоконференц-связи;\n\n2) разбирательство дела осуществляется в закрытом судебном заседании.\n\n(Дополнение статьей - Федеральный закон от 27.07.2010 № 228-ФЗ)","article_title":"Статья 153.1. Участие в судебном заседании путем использования систем видеоконференц-связи","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fe891764684949b24afc64b80aaf236e671e5e7b538ae7ebee5d99d856503231"},{"code_id":"APK_RF","article_number":"153.2","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, и иные участники арбитражного процесса могут участвовать в судебном заседании путем использования системы веб-конференции при условии заявления ими соответствующего ходатайства и при наличии в арбитражном суде технической возможности осуществления веб-конференции.\n\nУстановление личности гражданина, его представителя или представителя юридического лица, участвующих в судебном заседании путем использования системы веб-конференции, осуществляется с использованием информационно-технологических средств, обеспечивающих идентификацию лица без его личного присутствия (единой системы идентификации и аутентификации, единой биометрической системы).\n\nАрбитражный суд в электронном виде заблаговременно направляет лицам, участвующим в деле, информацию, необходимую для участия в судебном заседании путем использования системы веб-конференции. При отказе в удовлетворении ходатайства об участии в судебном заседании путем использования системы веб-конференции арбитражный суд в электронном виде направляет лицам, участвующим в деле, информацию о таком отказе с указанием его оснований. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n2. Арбитражный суд, рассматривающий дело, отказывает в удовлетворении ходатайства об участии в судебном заседании путем использования системы веб-конференции в случае, если:\n\n1) отсутствует техническая возможность для участия в судебном заседании с использованием системы веб-конференции;\n\n2) разбирательство дела осуществляется в закрытом судебном заседании.\n\n3. Лица, участвующие в деле, и иные участники арбитражного процесса, участвующие в судебном заседании путем использования системы веб-конференции, вправе в ходе судебного заседания подавать в арбитражный суд заявления, ходатайства и прилагаемые к ним документы в электронном виде.\n\n4. Арбитражный суд, рассматривающий дело, берет подписку у свидетелей, экспертов, переводчиков, участвующих в судебном заседании путем использования системы веб-конференции, о разъяснении им прав и обязанностей и предупреждении об ответственности за их нарушение, которая представляется в арбитражный суд в форме электронного документа, подписанного усиленной квалифицированной электронной подписью.\n\n5. При использ\n\nовании системы веб-конференции составляется протокол и ведется видеозапись судебного заседания. Материальный носитель видеозаписи судебного заседания приобщается к протоколу судебного заседания.\n\n(Дополнение статьей - Федеральный закон от 30.12.2021 № 440-ФЗ)","article_title":"Статья 153.2. Участие в судебном заседании путем использования системы веб-конференции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"29b4b9f6c2f1150fae3aa3855ea45b9023f943958e7041c077f920a15dc0eb33"},{"code_id":"APK_RF","article_number":"154","version_date":"2002-07-24","article_text":"1. При входе судей в зал судебного заседания все присутствующие в зале встают. Решение арбитражного суда все находящиеся в зале судебного заседания лица выслушивают стоя.\n\n2. Лица, участвующие в деле, и иные участники арбитражного процесса обращаются к арбитражному суду со словами: \"Уважаемый суд!\" Свои объяснения и показания суду, вопросы другим лицам, участвующим в деле, ответы на вопросы они дают стоя. Отступление от этого правила может быть допущено только с разрешения суда.","article_title":"Статья 154. Порядок в судебном заседании","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f5d05ecda0d7ed05c7b1efd033fc31479f5d744855b80fef59edb08ba7ea992"},{"code_id":"APK_RF","article_number":"155","version_date":"2002-07-24","article_text":"1. В ходе каждого судебного заседания арбитражного суда первой инстанции, а также при совершении отдельных процессуальных действий вне судебного заседания ведется протоколирование с использованием средств аудиозаписи и составляется протокол в письменной форме (далее также - протокол).\n\n2. Протокол является дополнительным средством фиксирования следующих данных о ходе судебного заседания:\n\n1) год, месяц, число и место проведения судебного заседания;\n\n2) время начала и окончания судебного заседания;\n\n3) наименование арбитражного суда, рассматривающего дело, состав суда;\n\n4) наименование и номер дела;\n\n5) сведения о предупреждении об уголовной ответственности переводчика за заведомо неправильный перевод, свидетелей за дачу заведомо ложных показаний и отказ от дачи показаний, эксперта за дачу заведомо ложного заключения;\n\n6) устные заявления и ходатайства лиц, участвующих в деле, консультации специалистов; (В редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\n7) соглашения сторон по фактическим обстоятельствам дела и заявленным требованиям и возражениям;\n\n8) определения, вынесенные судом без удаления из зала судебного заседания;\n\n9) отметка об использовании средств аудиозаписи, систем видеоконференц-связи либо системы веб-конференции и (или) иных технических средств, о проведении кино- и фотосъемки, видеозаписи, трансляции судебного заседания по радио, телевидению и в информационно-телекоммуникационной сети \"Интернет\" в ходе судебного заседания. При проведении трансляции судебного заседания указывается также наименование средства массовой информации или сайта в информационно-телекоммуникационной сети \"Интернет\", посредством которых осуществлялась трансляция; (В редакции федеральных законов от 29.07.2017 № 223-ФЗ, от 30.12.2021 № 440-ФЗ)\n\n10) дата составления протокола.\n\n3. В протоколе о совершении отдельного процессуального действия указываются также сведения, полученные в результате совершения этого процессуального действия.\n\n4. Секретарь судебного заседания или помощник судьи составляет протокол и обеспечивает использование средств аудиозаписи и (или) иных технических средств в ходе судебного заседания.\n\n5. Протокол может быть написан от руки или составлен с использованием технических средств. Протокол подписывается председательствующим в судебном заседании, секретарем судебного заседания или помощником судьи, который составлял протокол судебного заседания, не позднее следующего дня после дня окончания судебного заседания, а протокол о совершении отдельного процессуального действия - непосредственно после совершения отдельного процессуального действия.\n\n6. Протоколирование судебного заседания с использованием средств аудиозаписи ведется непрерывно в ходе судебного заседания. Материальный носитель аудиозаписи приобщается к протоколу.\n\nВ случае, если арбитражным судом проводится стенографическая запись, а также видеозапись судебного заседания, в протоколе, составленном в письменной форме, должны быть указаны сведения, предусмотренные пунктами 5, 6, 8 и 9 части 2 настоящей статьи. Материальный носитель видеозаписи приобщается к протоколу.\n\nЗамечания на протокол, представленные в арбитражный суд по истечении пятидневного срока, судом не рассматриваются и возвращаются лицу, представившему эти замечания. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 155. Протокол","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0c6e6e9862985d127a332f48f8eb80dc806a51b5bb4fa39a4f9b5ff17a800345"},{"code_id":"APK_RF","article_number":"156","version_date":"2002-07-24","article_text":"1. Непредставление отзыва на исковое заявление или дополнительных доказательств, которые арбитражный суд предложил представить лицам, участвующим в деле, не является препятствием к рассмотрению дела по имеющимся в деле доказательствам.\n\n2. Стороны вправе известить арбитражный суд о возможности рассмотрения дела в их отсутствие.\n\n3. При неявке в судебное заседание арбитражного суда истца и (или) ответчика, надлежащим образом извещенных о времени и месте судебного разбирательства, суд вправе рассмотреть дело в их отсутствие.\n\n4. В случае, если в судебное заседание не явились лица, участвующие в деле, а их явка в соответствии с настоящим Кодексом была признана обязательной арбитражным судом, суд может наложить на указанных лиц судебный штраф в порядке и в размерах, которые предусмотрены в главе 11 настоящего Кодекса.\n\n5. При неявке в судебное заседание иных лиц, участвующих в деле и надлежащим образом извещенных о времени и месте судебного разбирательства, суд рассматривает дело в их отсутствие.","article_title":"Статья 156. Рассмотрение дела при непредставлении отзыва на исковое заявление, дополнительных доказательств, а также в отсутствие лиц, участвующих в деле","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"46df8776d28fcdbf56af022e3a4c6cb097a3c4efca2fe07b0ff93a14f784c35a"},{"code_id":"APK_RF","article_number":"157","version_date":"2002-07-24","article_text":"1. При неявке в судебное заседание экспертов, свидетелей, переводчиков, надлежащим образом извещенных о времени и месте судебного заседания, арбитражный суд выносит определение об отложении судебного разбирательства, если стороны не заявили ходатайство о рассмотрении дела в отсутствие указанных лиц.\n\n2. В случае, если вызванные в судебное заседание эксперт, свидетель, переводчик не явились в суд по причинам, признанным судом неуважительными, суд может наложить на них судебный штраф в порядке и в размере, которые установлены в главе 11 настоящего Кодекса.","article_title":"Статья 157. Последствия неявки в судебное заседание экспертов, свидетелей, переводчиков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d8d400f1dde59d38443fa39ff5f8f29cdc24c5d0115ed49e59c7e787a3777b85"},{"code_id":"APK_RF","article_number":"158","version_date":"2002-07-24","article_text":"1. Арбитражный суд откладывает судебное разбирательство в случаях, предусмотренных настоящим Кодексом, а также в случае неявки в судебное заседание лица, участвующего в деле, если в отношении этого лица у суда отсутствуют сведения об извещении его о времени и месте судебного разбирательства.\n\nСудебное разбирательство также может быть отложено по решению председателя арбитражного суда, заместителя председателя арбитражного суда или председателя судебного состава в случае болезни судьи или по иным причинам невозможности проведения судебного заседания на срок, не превышающий одного месяца. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 228-ФЗ) (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n10. Судебное разбирательство в новом судебном заседании возобновляется с того момента, с которого оно было отложено. Повторное рассмотрение доказательств, исследованных до отложения судебного разбирательства, не производится.","article_title":"Статья 158. Отложение судебного разбирательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"76dfdec1b4fb46344dd1c16cf7f019876246e193ec0a28d1d3dfb27134239244"},{"code_id":"APK_RF","article_number":"16","version_date":"2002-07-24","article_text":"1. Вступившие в законную силу судебные акты арбитражного суда являются обязательными для органов государственной власти, органов местного самоуправления, иных органов, организаций, должностных лиц и граждан и подлежат исполнению на всей территории Российской Федерации.\n\nТребования арбитражного суда о представлении доказательств, сведений и других материалов, даче объяснений, разъяснений, заключений и иные требования, связанные с рассматриваемым делом, являются также обязательными и подлежат исполнению органами, организациями и лицами, которым они адресованы.\n\n11. Специализированный арбитражный суд в целях получения разъяснений, консультаций и выяснения профессионального мнения ученых, специалистов и прочих лиц, обладающих теоретическими и практическими познаниями по существу разрешаемого специализированным арбитражным судом спора, может также направлять запросы.\n\nЗапросы о даче разъяснений, консультаций и об изложении профессиональных мнений по рассматриваемым специализированным арбитражным судом делам обязательны для всех органов, организаций и лиц, которым они адресованы.\n\nЗапросы должны быть рассмотрены и ответ по результатам их рассмотрения должен быть направлен в специализированный арбитражный суд в течение месяца со дня получения этих запросов, если иной срок не указан специализированным арбитражным судом.\n\n(Дополнение частью - Федеральный закон от 08.12.2011 № 422-ФЗ)\n\n2. Неисполнение судебных актов, а также невыполнение требований арбитражных судов влечет за собой ответственность, установленную настоящим Кодексом и другими федеральными законами.\n\n3. Обязательность судебных актов не лишает лиц, не участвовавших в деле, возможности обратиться в арбитражный суд за защитой нарушенных этими актами их прав и законных интересов путем обжалования указанных актов.\n\n4. Признание и обязательность исполнения на территории Российской Федерации судебных актов, принятых иностранными судами, иностранных арбитражных решений определяются международным договором Российской Федерации, федеральным законом.","article_title":"Статья 16. Обязательность судебных актов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cee55c5c6421b2e0f130feb218c533fc67f6afcc1a9f722830bf7a87d5248fb4"},{"code_id":"APK_RF","article_number":"160","version_date":"2002-07-24","article_text":"1. В случае, если в одном заявлении соединены требование об установлении оснований ответственности ответчика и связанное с ним требование о применении мер ответственности, арбитражный суд вправе с согласия сторон рассмотреть такие требования в раздельных судебных заседаниях.\n\nО рассмотрении дела в раздельных судебных заседаниях выносится определение.\n\n2. При отказе в удовлетворении требования об установлении оснований ответственности ответчика арбитражный суд не рассматривает связанное с ним требование о применении мер ответственности и второе судебное заседание не проводит.\n\n3. В случае удовлетворения требования об установлении оснований ответственности ответчика арбитражный суд сразу же или после перерыва, срок которого не может превышать пять дней, вправе провести второе судебное заседание и в этом судебном заседании рассмотреть требование о применении мер ответственности, в том числе определить размер взыскиваемой суммы. По результатам рассмотрения арбитражный суд принимает решение по всем заявленным требованиям.\n\n4. В случае, если в судебном заседании объявлялся перерыв, во время которого стороны достигли договоренности или урегулировали спор в части требований о применении мер ответственности, арбитражный суд не рассматривает эти требования и прекращает производство по делу в части требований о применении мер ответственности при условии, что истец обратился с отказом в письменной форме от иска или стороны заключили мировое соглашение в этой части требований и отказ принят либо мировое соглашение утверждено судом, на что указывается в судебном акте арбитражного суда.","article_title":"Статья 160. Рассмотрение дела в раздельных заседаниях арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6bb0c5926f132a9f17b3b60e3792ec3d39ff6a423f8e0d23716dc563be2eb7b6"},{"code_id":"APK_RF","article_number":"161","version_date":"2002-07-24","article_text":"1. Если лицо, участвующее в деле, обратится в арбитражный суд с заявлением в письменной форме о фальсификации доказательства, представленного другим лицом, участвующим в деле, суд:\n\n1) разъясняет уголовно-правовые последствия такого заявления;\n\n2) исключает оспариваемое доказательство с согласия лица, его представившего, из числа доказательств по делу;\n\n3) проверяет обоснованность заявления о фальсификации доказательства, если лицо, представившее это доказательство, заявило возражения относительно его исключения из числа доказательств по делу.\n\nВ этом случае арбитражный суд принимает предусмотренные федеральным законом меры для проверки достоверности заявления о фальсификации доказательства, в том числе назначает экспертизу, истребует другие доказательства или принимает иные меры.\n\n2. Результаты рассмотрения заявления о фальсификации доказательства арбитражный суд отражает в протоколе судебного заседания.","article_title":"Статья 161. Заявление о фальсификации доказательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4e17eccc811950c52c43a5697ba492a123f0d37db03582f94c168cbc9792d6c"},{"code_id":"APK_RF","article_number":"163","version_date":"2002-07-24","article_text":"1. Арбитражный суд по ходатайству лица, участвующего в деле, или по своей инициативе может объявить перерыв в судебном заседании.\n\n2. Перерыв в судебном заседании может быть объявлен на срок, не превышающий десяти дней. (В редакции  Федерального закона\n\n3. На перерыв в пределах дня судебного заседания и время, когда заседание будет продолжено, указывается в протоколе судебного заседания.\n\nО перерыве на более длительный срок арбитражный суд выносит определение, которое заносится в протокол судебного заседания. В определении указываются время и место продолжения судебного заседания.\n\n4. После окончания перерыва судебное заседание продолжается, о чем объявляет председательствующий в судебном заседании. Повторное рассмотрение исследованных до перерыва доказательств не производится, в том числе при замене представителей лиц, участвующих в деле.\n\n5. Лица, участвующие в деле и присутствовавшие в зале судебного заседания до объявления перерыва, считаются надлежащим образом извещенными о времени и месте судебного заседания, и их неявка в судебное заседание после окончания перерыва не является препятствием для его продолжения.","article_title":"Статья 163. Перерыв в судебном заседании","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a5105f88c84d06170ea127a0c947e4202a30519d3713b06efd2fbb1787591b1a"},{"code_id":"APK_RF","article_number":"164","version_date":"2002-07-24","article_text":"1. После завершения исследования всех доказательств председательствующий в судебном заседании выясняет у лиц, участвующих в деле, не желают ли они чем-либо дополнить материалы дела. При отсутствии таких заявлений председательствующий в судебном заседании объявляет исследование доказательств законченным и суд переходит к судебным прениям.\n\n2. Судебные прения состоят из устных выступлений лиц, участвующих в деле, и их представителей. В этих выступлениях они обосновывают свою позицию по делу.\n\n3. В судебных прениях первыми выступают истец и (или) его представитель, затем - третье лицо, заявляющее самостоятельные требования относительно предмета спора, ответчик и (или) его представитель. Третье лицо, не заявляющее самостоятельных требований относительно предмета спора, выступает после истца или после ответчика, на стороне которого оно участвует в деле.\n\nПрокурор, представитель государственного органа, органа местного самоуправления и иного органа, обратившиеся в арбитражный суд в соответствии со статьями 52 и 53 настоящего Кодекса, выступают в судебных прениях первыми.\n\n4. Участники судебных прений не вправе ссылаться на обстоятельства, которые судом не выяснялись, и на доказательства, которые не исследовались в судебном заседании или признаны судом недопустимыми.\n\n5. После выступления всех участников судебных прений каждый из них вправе выступить с репликами. Право последней реплики всегда принадлежит ответчику и (или) его представителю.","article_title":"Статья 164. Судебные прения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1de894768f93f93cc7a138c2afcb60cb3c286bbeeb2259325b19e9d6a3b70c84"},{"code_id":"APK_RF","article_number":"165","version_date":"2002-07-24","article_text":"1. В случае, если арбитражный суд во время или после судебных прений признает необходимым выяснить дополнительные обстоятельства или исследовать новые доказательства, суд возобновляет исследование доказательств, на что указывает в протоколе судебного заседания.\n\n2. После окончания дополнительного исследования доказательств судебные прения происходят в общем порядке, установленном настоящим Кодексом.","article_title":"Статья 165. Возобновление исследования доказательств","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5aa2c41238dbb83912e7731f943b0fc6d53d6f9e5ba05738eac7eb3199ea1f2e"},{"code_id":"APK_RF","article_number":"166","version_date":"2002-07-24","article_text":"После исследования доказательств по делу и судебных прений председательствующий в судебном заседании объявляет рассмотрение дела по существу законченным и арбитражный суд удаляется для принятия решения, о чем объявляется присутствующим в зале судебного заседания.","article_title":"Статья 166. Окончание рассмотрения дела по существу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"acf8ab22b4a43a8da6cfa28efb3a474615065a479ebcdb323672e43f1a725fdd"},{"code_id":"APK_RF","article_number":"167","version_date":"2002-07-24","article_text":"1. При разрешении спора по существу арбитражный суд первой инстанции принимает решение. Решение принимается именем Российской Федерации.\n\n2. Арбитражный суд может принять отдельное решение по каждому из требований, объединенных в одном деле.\n\n3. Решение принимается судьями, участвующими в судебном заседании, в условиях, обеспечивающих тайну совещания судей.\n\n4. В помещении, в котором арбитражный суд проводит совещание и принимает судебный акт, могут находиться только лица, входящие в состав суда, рассматривающего дело. Запрещается доступ в это помещение других лиц, а также иные способы общения с лицами, входящими в состав суда.","article_title":"Статья 167. Принятие решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b8c7b2bd2be9791465d865120685f6bf57628cdc31bc4bcdae9760d37e0ce3c"},{"code_id":"APK_RF","article_number":"168","version_date":"2002-07-24","article_text":"1. При принятии решения арбитражный суд оценивает доказательства и доводы, приведенные лицами, участвующими в деле, в обоснование своих требований и возражений; определяет, какие обстоятельства, имеющие значение для дела, установлены и какие обстоятельства не установлены, какие законы и иные нормативные правовые акты следует применить по данному делу; устанавливает права и обязанности лиц, участвующих в деле; решает, подлежит ли иск удовлетворению.\n\n2. При принятии решения арбитражный суд решает вопросы о сохранении действия мер по обеспечению иска или об отмене обеспечения иска либо об обеспечении исполнения решения; при необходимости устанавливает порядок и срок исполнения решения; определяет дальнейшую судьбу вещественных доказательств, распределяет судебные расходы, а также решает иные вопросы, возникшие в ходе судебного разбирательства.\n\n3. Арбитражный суд, признав при принятии решения необходимым дополнительно исследовать доказательства или продолжить выяснение обстоятельств, имеющих значение для дела, возобновляет судебное разбирательство, о чем выносит определение.","article_title":"Статья 168. Вопросы, разрешаемые при принятии решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb26b15d73308774d5af9fadd8196f9e35097e2081b64605159af5ff40c0eb3c"},{"code_id":"APK_RF","article_number":"169","version_date":"2002-07-24","article_text":"1. Решение арбитражного суда излагается в виде отдельного документа.\n\nРешение выполняется в форме электронного документа. При отсутствии в арбитражном суде технической возможности для выполнения решения в форме электронного документа решение выполняется на бумажном носителе.\n\n(Часть в редакции Федерального закона от 23.06.2016 № 220-ФЗ)\n\n2. В решении должны быть указаны мотивы его принятия, и оно должно быть изложено языком, понятным для лиц, участвующих в деле, и других лиц.\n\n3. Решение подписывается судьей, а в случае коллегиального рассмотрения дела - всеми судьями, участвовавшими в принятии решения, в том числе судьей, имеющим особое мнение.\n\n4. Исправления в решении должны быть оговорены и удостоверены подписями всех судей в совещательной комнате до объявления решения.","article_title":"Статья 169. Изложение решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6e5cdfb2e7c4303287eebb7d80ea583972ef11b6ae04f674f918dac6cdc4d6e5"},{"code_id":"APK_RF","article_number":"17","version_date":"2002-07-24","article_text":"1. Дела в первой инстанции арбитражного суда рассматриваются судьей единолично, если коллегиальное рассмотрение дела не предусмотрено настоящей статьей. Коллегиальное рассмотрение дел в арбитражном суде первой инстанции осуществляется в составе трех судей или судьи и двух арбитражных заседателей.\n\n2. В первой инстанции арбитражного суда коллегиальным составом судей рассматриваются:\n\n1) (Пункт утратил силу - Федеральный закон от 28.06.2014 № 186-ФЗ)\n\n2) дела об оспаривании нормативных правовых актов;\n\n3) (Пункт утратил силу - Федеральный закон от 12.07.2011 № 210-ФЗ)\n\n4) дела, направленные в арбитражный суд первой инстанции на новое рассмотрение с указанием на коллегиальное рассмотрение;\n\n5) дела, решения о коллегиальном рассмотрении которых приняты председателем судебного состава в связи с их особой сложностью на основании мотивированного заявления судьи; (Дополнение пунктом - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\n6) дела, относящиеся к подсудности Суда по интеллектуальным правам. (Дополнение пунктом - Федеральный закон от 08.12.2011 № 422-ФЗ)\n\n3. Арбитражный суд первой инстанции в составе судьи и двух арбитражных заседателей рассматривает экономические споры и иные дела, возникающие из гражданских и иных правоотношений, если какая-либо из сторон заявит ходатайство о рассмотрении дела с участием арбитражных заседателей.\n\nНе подлежат рассмотрению с участием арбитражных заседателей дела, предусмотренные частью 2 настоящей статьи, а также дела, возникающие из административных и иных публичных правоотношений, и дела особого производства.\n\n4. Дела в арбитражном суде апелляционной и кассационной инстанций, а также в порядке надзора рассматриваются коллегиально в составе трех или иного нечетного количества судей, если иное не установлено настоящим Кодексом.\n\nПри коллегиальном рассмотрении дела один из судей председательствует в судебном заседании.\n\n5. В случае, если настоящим Кодексом судье предоставлено право единолично рассматривать дела и разрешать отдельные процессуальные вопросы, судья действует от имени арбитражного суда.","article_title":"Статья 17. Единоличное и коллегиальное рассмотрение дел","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e90baa7722ef0beb1bb3b359abb162c4d52e076a5c1788afb711978a50a3cc21"},{"code_id":"APK_RF","article_number":"170","version_date":"2002-07-24","article_text":"1. Решение арбитражного суда должно состоять из вводной, описательной, мотивировочной и резолютивной частей.\n\n2. Вводная часть решения должна содержать наименование арбитражного суда, принявшего решение; состав суда, фамилию лица, которое вело протокол судебного заседания; номер дела, дату и место принятия решения; предмет спора; наименования лиц, участвующих в деле, фамилии лиц, присутствовавших в судебном заседании, с указанием их полномочий.\n\n3. Описательная часть решения должна содержать краткое изложение заявленных требований и возражений, объяснений, заявлений и ходатайств лиц, участвующих в деле.\n\n4. В мотивировочной части решения должны быть указаны:\n\n1) фактические и иные обстоятельства дела, установленные арбитражным судом;\n\n2) доказательства, на которых основаны выводы суда об обстоятельствах дела и доводы в пользу принятого решения; мотивы, по которым суд отверг те или иные доказательства, принял или отклонил приведенные в обоснование своих требований и возражений доводы лиц, участвующих в деле;\n\n3) законы и иные нормативные правовые акты, которыми руководствовался суд при принятии решения, и мотивы, по которым суд не применил законы и иные нормативные правовые акты, на которые ссылались лица, участвующие в деле.\n\nВ мотивировочной части решения должны содержаться также обоснования принятых судом решений и обоснования по другим вопросам, указанным в части 5 настоящей статьи.\n\nВ случае признания иска ответчиком в мотивировочной части решения может быть указано только на признание иска и принятие его судом.\n\nВ случае отказа в иске в связи с признанием неуважительными причин пропуска срока исковой давности или срока обращения в суд в мотивировочной части решения суда указывается только на установление судом данных обстоятельств.\n\nВ мотивировочной части решения могут содержаться ссылки на постановления Пленума Верховного Суда Российской Федерации и сохранившие силу постановления Пленума Высшего Арбитражного Суда Российской Федерации по вопросам судебной практики, на постановления Президиума Верховного Суда Российской Федерации и сохранившие силу постановления Президиума Высшего Арбитражного Суда Российской Федерации, а также на обзоры судебной практики Верховного Суда Российской Федерации, утвержденные Президиумом Верховного Суда Российской Федерации.\n\n(Часть в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\nПри полном или частичном удовлетворении первоначального и встречного исков в резолютивной части решения указывается денежная сумма, подлежащая взысканию в результате зачета.\n\nЕсли арбитражный суд установил порядок исполнения решения или принял меры по обеспечению его исполнения, на это указывается в резолютивной части решения.","article_title":"Статья 170. Содержание решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"11b84412950acdc75ecbd7612b4564c0f87fecf83cab11f770c00b76e390f336"},{"code_id":"APK_RF","article_number":"171","version_date":"2002-07-24","article_text":"1. При удовлетворении требования о взыскании денежных средств в резолютивной части решения арбитражный суд указывает общий размер подлежащих взысканию денежных сумм с раздельным определением основной задолженности, убытков, неустойки (штрафа, пеней) и процентов.\n\n2. При присуждении имущества арбитражный суд указывает наименование имущества, подлежащего передаче истцу, его стоимость и место нахождения.","article_title":"Статья 171. Решение о взыскании денежных средств и присуждении имущества","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cffde025f93253e972299cf36b7959e22ef3bc73f66ffb8b0471e38f9c693c85"},{"code_id":"APK_RF","article_number":"172","version_date":"2002-07-24","article_text":"При удовлетворении требования относительно спора о признании не подлежащим исполнению исполнительного или иного документа, по которому взыскание производится в бесспорном (безакцептном) порядке, в том числе на основании исполнительной надписи нотариуса, в резолютивной части решения арбитражный суд указывает наименование, номер, дату выдачи документа, не подлежащего исполнению, и денежную сумму, не подлежащую списанию.","article_title":"Статья 172. Решение о признании не подлежащим исполнению исполнительного или иного документа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ad4ef4ad5ee013285735b937e4040514a420f538b5b079a5f0f26f936092a5ce"},{"code_id":"APK_RF","article_number":"173","version_date":"2002-07-24","article_text":"По спору, возникшему при заключении или изменении договора, в резолютивной части решения указывается вывод арбитражного суда по каждому спорному условию договора, а по спору о понуждении заключить договор указываются условия, на которых стороны обязаны заключить договор.","article_title":"Статья 173. Решение о заключении или об изменении договора","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5c1fad081c2def206fc15796f0f83f010825ceab9df5275f21d8894a8e521556"},{"code_id":"APK_RF","article_number":"174","version_date":"2002-07-24","article_text":"1. При принятии решения, обязывающего ответчика совершить определенные действия, не связанные со взысканием денежных средств или с передачей имущества, арбитражный суд в резолютивной части решения указывает лицо, обязанное совершить эти действия, а также место и срок их совершения.\n\n2. При принятии решения, обязывающего организацию совершить определенные действия, не связанные со взысканием денежных средств или с передачей имущества, арбитражный суд в резолютивной части решения может указать руководителя или иное лицо, на которых возлагается исполнение решения, а также срок исполнения.\n\n3. Арбитражный суд может указать в решении, что истец вправе осуществить соответствующие действия за счет ответчика со взысканием с него необходимых расходов в случае, если ответчик не исполнит решение в течение установленного срока.","article_title":"Статья 174. Решение, обязывающее ответчика совершить определенные действия","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"389d2d8778f75e1f71373a78b6adddc0447baee9e6c922a946bfc3ce0651aa82"},{"code_id":"APK_RF","article_number":"175","version_date":"2002-07-24","article_text":"1. При принятии решения в пользу нескольких истцов арбитражный суд указывает, в какой части (доле) оно относится к каждому из них, или указывает, что право требования является солидарным.\n\n2. При принятии решения против нескольких ответчиков арбитражный суд указывает, в какой части (доле) каждый из ответчиков должен выполнить решение, или указывает, что их ответственность является солидарной.","article_title":"Статья 175. Решение в пользу нескольких истцов или против нескольких ответчиков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b3b9a6e8651fe7ac60d967958e7991ff6748f9aaf42e22c94e4aa39fd265ca99"},{"code_id":"APK_RF","article_number":"176","version_date":"2002-07-24","article_text":"1. Решение арбитражного суда объявляется председательствующим в том судебном заседании, в котором закончено рассмотрение дела по существу, после принятия решения арбитражного суда.\n\n2. В судебном заседании, в котором закончено рассмотрение дела по существу, может быть объявлена только резолютивная часть принятого решения. В этом случае арбитражный суд объявляет, когда будет изготовлено решение в полном объеме и разъясняет порядок доведения его до сведения лиц, участвующих в деле.\n\nИзготовление решения в полном объеме может быть отложено на срок, не превышающий десяти дней. Дата изготовления решения в полном объеме считается датой принятия решения. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n3. Объявленная резолютивная часть решения должна быть подписана всеми судьями, участвовавшими в рассмотрении дела и принятии решения, и приобщена к делу.\n\nПри выполнении резолютивной части решения в форме электронного документа дополнительно выполняется экземпляр данной резолютивной части решения на бумажном носителе, который также приобщается к делу. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ)\n\n4. Председательствующий в судебном заседании после объявления решения разъясняет порядок его обжалования.","article_title":"Статья 176. Объявление решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c2c64f4f2fe285eb406fbb6e5391387cb5c03d0f14fb8eb57b8b9371a36d80f2"},{"code_id":"APK_RF","article_number":"177","version_date":"2002-07-24","article_text":"1. Решение, выполненное в форме электронного документа, направляется лицам, участвующим в деле, посредством его размещения в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" в режиме ограниченного доступа не позднее следующего дня после дня его принятия.\n\nРешение, выполненное в форме электронного документа, может быть также направлено лицам, участвующим в деле, посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия.\n\nПо ходатайству указанных лиц копии решения на бумажном носителе могут быть направлены им в пятидневный срок со дня поступления соответствующего ходатайства в арбитражный суд заказным письмом с уведомлением о вручении или вручены им под расписку.\n\nВ случае, если решение выполнено только на бумажном носителе, арбитражный суд направляет копии решения лицам, участвующим в деле, в пятидневный срок со дня принятия решения заказным письмом с уведомлением о вручении или вручает им под расписку.\n\n(Часть в редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В случаях и в порядке, которые предусмотрены настоящим Кодексом, арбитражный суд направляет копии решения и иным лицам.\n\n3. Повторная выдача копий решения и других судебных актов лицам, участвующим в деле, оплачивается государственной пошлиной.","article_title":"Статья 177. Направление решения лицам, участвующим в деле","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb9f05bd05903f457040387b68b7dbbc9198b64c026d83321e6bebb32453aa4d"}]$law7d0002$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
